import type { GeospatialCamera, GeospatialLimits } from "@babylonjs/lite";

interface ModeLimitState {
    limits: GeospatialLimits;
    radius: number;
    yaw: number;
    setOrientation: GeospatialCamera["_setOrientation"];
}

const states = new WeakMap<GeospatialCamera, ModeLimitState>();

function clamp(value: number, min: number, max: number): number {
    return Math.min(Math.max(value, min), max);
}

// NaN input keeps the fallback value so a bad write cannot poison the state.
function clampOr(value: number, fallback: number, min: number, max: number): number {
    return clamp(Number.isNaN(value) ? fallback : value, min, max);
}

function attach(camera: GeospatialCamera, state: ModeLimitState): void {
    Object.defineProperty(camera, "radius", {
        configurable: true,
        enumerable: true,
        get: () => state.radius,
        set: (value: number) => {
            state.radius = clampOr(value, state.radius, state.limits.radiusMin, state.limits.radiusMax);
        },
    });

    Object.defineProperty(camera, "yaw", {
        configurable: true,
        enumerable: true,
        get: () => state.yaw,
        set: (value: number) => {
            state.yaw = clampOr(value, state.yaw, state.limits.yawMin, state.limits.yawMax);
        },
    });

    const original = state.setOrientation;
    camera._setOrientation = (yaw, pitch, radius, center) => {
        original.call(
            camera,
            clampOr(yaw, state.yaw, state.limits.yawMin, state.limits.yawMax),
            pitch,
            clampOr(radius, state.radius, state.limits.radiusMin, state.limits.radiusMax),
            center,
        );
    };
}

export function useModeLimits(camera: GeospatialCamera, limits: GeospatialLimits): void {
    let state = states.get(camera);
    if (!state) {
        state = {
            limits,
            radius: camera.radius,
            yaw: camera.yaw,
            setOrientation: camera._setOrientation,
        };
        states.set(camera, state);
        attach(camera, state);
    }

    state.limits = limits;
    camera.limits = limits;

    // Re-assigning through the accessors clamps the current values into this mode's ranges.
    camera.radius = state.radius;
    camera.yaw = state.yaw;
}
```

I wrote `useModeLimits` to intercept writes to `radius` and `yaw` with accessors on the camera, clamp them to the active mode's `radiusMin`/`radiusMax` and `yawMin`/`yawMax`, wrap `_setOrientation` the same way, and point `camera.limits` at the mode's object without modifying it. Switching modes reuses the same interception and updates the active limits, so it applies the new ranges.

Things I'm not sure of:
- I haven't checked the file on disk, and I couldn't run the code or check it against the library, which isn't on this machine.
- If the library writes orientation through private fields instead of `radius`, `yaw`, or `_setOrientation`, those writes bypass the clamp.
- I assumed `radiusMin`/`radiusMax` and `yawMin`/`yawMax` are absolute values in the camera's units. I didn't use `clampZoomDistance` because its semantics aren't clear from the declarations.
- I assumed the yaw range doesn't wrap (`yawMin <= yawMax`).
- `Object.defineProperty` will throw if the camera's `radius` or `yaw` properties are non-configurable.
